#define main original_main
#include "../muon-cuda/main.cu"
#undef main
#include <vector>
#include <string>
struct Case{int P,Q;bool dense;float scale;std::vector<float>p0,m0,g0;float*p,*m,*g,*ss;bf16*x,*a,*a2,*b,*bx;};
static void step(Case&c){int P=c.P,Q=c.Q,N=P*Q,mm=std::min(P,Q),nn=std::max(P,Q);dim3 gn(((N+3)/4+255)/256),gm(((mm*mm+3)/4+255)/256);if(P>Q)momentum_transpose<<<dim3((Q+31)/32,(P+31)/32),dim3(32,8)>>>(c.m,c.g,c.x,.95f,P,Q);else momentum_update<<<gn,256>>>(c.m,c.g,c.x,.95f,N);CHECK_CUDA(cudaMemset(c.ss,0,4));sumsq_kernel<<<256,256>>>(c.x,c.ss,N);normalize<<<gn,256>>>(c.x,c.ss,N);for(int k=0;k<5;++k){rgemm(CUBLAS_OP_N,CUBLAS_OP_T,mm,mm,nn,c.x,c.x,c.a);rgemm(CUBLAS_OP_N,CUBLAS_OP_N,mm,mm,mm,c.a,c.a,c.a2);combineB<<<gm,256>>>(c.a,c.a2,c.b,NS_B,NS_C,mm*mm);rgemm(CUBLAS_OP_N,CUBLAS_OP_N,mm,nn,mm,c.b,c.x,c.bx);updateX<<<gn,256>>>(c.x,c.bx,NS_A,N);}if(P>Q)transpose_param_update<<<dim3((P+31)/32,(Q+31)/32),dim3(32,8)>>>(c.p,c.x,.02f,0.f,c.scale,P,Q);else param_update<<<gn,256>>>(c.p,c.x,.02f,0.f,c.scale,N);}
static void capture(std::vector<double>&out,float*p,int n){std::vector<float>x(n);CHECK_CUDA(cudaMemcpy(x.data(),p,n*4,cudaMemcpyDeviceToHost));for(float v:x)out.push_back(v);}
static void capture(std::vector<double>&out,bf16*p,int n){std::vector<bf16>x(n);CHECK_CUDA(cudaMemcpy(x.data(),p,n*2,cudaMemcpyDeviceToHost));for(auto v:x)out.push_back(__bfloat162float(v));}
int main(){CHECK_CUBLAS(cublasCreate(&g_handle));std::vector<Case>cases;std::vector<double>prefix;int shapes[][3]={{16,32,0},{32,16,0},{17,33,1},{33,17,1}};for(auto&shape:shapes){Case c;c.P=shape[0];c.Q=shape[1];c.dense=shape[2];int n=c.P*c.Q,mm=std::min(c.P,c.Q);c.scale=sqrtf(fmaxf(1.f,float(c.P)/c.Q));for(int i=0;i<n;++i){c.p0.push_back(float(i*11%37-18)/64);c.m0.push_back(c.dense?float(i*13%29-14)/64:(i/c.Q==i%c.Q?float(i%c.Q+1)/64:0));c.g0.push_back(c.dense?float(i*7%31-15)/128:(i/c.Q==i%c.Q?float(i%c.Q+1)/128:0));}for(auto&data:{c.p0,c.m0,c.g0})for(float v:data)prefix.push_back(v);prefix.insert(prefix.end(),{double(c.P),double(c.Q),2,double(.95f),double(.02f),0,double(c.scale),double(c.dense)});CHECK_CUDA(cudaMalloc(&c.p,n*4));CHECK_CUDA(cudaMalloc(&c.m,n*4));CHECK_CUDA(cudaMalloc(&c.g,n*4));CHECK_CUDA(cudaMalloc(&c.ss,4));CHECK_CUDA(cudaMalloc(&c.x,n*2));CHECK_CUDA(cudaMalloc(&c.a,mm*mm*2));CHECK_CUDA(cudaMalloc(&c.a2,mm*mm*2));CHECK_CUDA(cudaMalloc(&c.b,mm*mm*2));CHECK_CUDA(cudaMalloc(&c.bx,n*2));CHECK_CUDA(cudaMemcpy(c.g,c.g0.data(),n*4,cudaMemcpyHostToDevice));cases.push_back(c);}auto run=[&](Case&c,std::vector<double>&out){int n=c.P*c.Q,mm=std::min(c.P,c.Q);CHECK_CUDA(cudaMemcpy(c.p,c.p0.data(),n*4,cudaMemcpyHostToDevice));CHECK_CUDA(cudaMemcpy(c.m,c.m0.data(),n*4,cudaMemcpyHostToDevice));CHECK_CUDA(cudaDeviceSynchronize());auto t=std::chrono::steady_clock::now();for(int i=0;i<2;++i)step(c);CHECK_CUDA(cudaDeviceSynchronize());double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/2;capture(out,c.p,n);capture(out,c.m,n);capture(out,c.x,n);capture(out,c.a,mm*mm);capture(out,c.a2,mm*mm);capture(out,c.b,mm*mm);capture(out,c.bx,n);capture(out,c.ss,1);return elapsed;};for(auto&c:cases){std::vector<double>unused;run(c,unused);}for(int trial=1;trial<=5;++trial){auto out=prefix;double elapsed=0;for(auto&c:cases)elapsed+=run(c,out);bool ok=true;for(double v:out)ok&=std::isfinite(v);std::string path="trial_"+std::to_string(trial)+".bin";FILE*f=fopen(path.c_str(),"wb");fwrite(out.data(),8,out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"timing_region\":\"sum_four_two_step_optimizer_means\",\"jit_excluded\":true,\"internal_repeats\":2,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",out.size(),path.c_str(),out.size());if(!ok)return 3;}for(auto&c:cases){cudaFree(c.p);cudaFree(c.m);cudaFree(c.g);cudaFree(c.ss);cudaFree(c.x);cudaFree(c.a);cudaFree(c.a2);cudaFree(c.b);cudaFree(c.bx);}cublasDestroy(g_handle);return 0;}
